def one_color_rows(grid):
    """Indices of rows that are a single color throughout."""
    return {i for i, row in enumerate(grid) if len(set(row)) == 1}

def one_color_cols(grid):
    """Indices of columns that are a single color throughout."""
    return {j for j in range(len(grid[0])) if len({row[j] for row in grid}) == 1}

def recolor_lines(grid, new):
    """Every cell lying on a one-color row or column recolored to new."""
    rows, cols = one_color_rows(grid), one_color_cols(grid)
    return [[new if (i in rows or j in cols) else v for j, v in enumerate(row)]
            for i, row in enumerate(grid)]

